#define RAND         0x0a034UL
#define DEPUTY       0x0bbbaUL
#define REPORT       0x2bfe2UL
#define ELEMENT_UNIT 0x2866cUL
#define REMOVE_UNIT  0x2990eUL
#define REMOVE_LIST  0x299d6UL
