    put_word(ds, (uint16_t)(unit + 8), 0);
    put_word(ds, (uint16_t)(unit + 6), 0);
    put_word(ds, (uint16_t)(unit + 10), 0);
    call1(ds, event, REMOVE_LIST, unit);
    return;
