    put_word(ds, LOST_ELEMENT, element);
    put_word(ds, LOST_UNIT, unit);
    opeu_battle_report_loss(ds, event);
    put_word(ds, LOST_ELEMENT, 0);
    put_word(ds, LOST_UNIT, 0);
